/**
 * Resolve a pulled automation's Run Function `procedure` task to the exact
 * catalog bag key `src/catalog/org.ts` assigned it — `uniqueCatalogKey`
 * there disambiguates same-name overloaded Snowflake procedures with a
 * numeric suffix (`shippingRate`, `shippingRate2`, …) across the WHOLE
 * CloudLink's procedure list, a decision `entities/automation/from-tf.ts`
 * cannot reconstruct from one `data.elementum_stored_function` block alone.
 *
 * `elementum pull app`/`pull element` both require a prior `pull org
 * --data-only` (org.ts is a hard prerequisite), so the already-pulled
 * org.ts always carries the current, authoritative key assignment. Loading
 * it through the same native workspace loader `elementum build` uses for
 * the same file (`engine/build/build.ts`'s `loadOrgRefs`) gives back real
 * `ProcedureRef` objects — no text parsing, no drift from the renderer's
 * exact output format.
 */
import { existsSync } from "node:fs";
import { join } from "node:path";
import { createWorkspaceLoader } from "../workspace/loader.js";
/**
 * CloudLink display name + exact Snowflake signature → one discriminator
 * string. Shared by the org.ts reader below and
 * `entities/automation/from-tf.ts`'s `elementum_stored_function` decode
 * branch — both MUST derive it the same way, or a pulled reference silently
 * resolves to the wrong overload's key.
 */
export function procedureDiscriminator(cloudLinkName, name, database, schema, parameterTypes) {
    return [cloudLinkName, name, database, schema, parameterTypes.join(",")].join("\0");
}
/**
 * Discriminator → the org catalog's disambiguated procedure bag key, read
 * back from the already-pulled `<orgRoot>/org.ts`. Empty when org.ts is
 * missing or carries no procedures — callers degrade to the base
 * `sanitizeName` key, which is already correct whenever there's no
 * same-name overload to disambiguate.
 */
export async function loadProcedureCatalogKeys(orgRoot) {
    const map = new Map();
    const orgPath = join(orgRoot, "org.ts");
    if (!existsSync(orgPath))
        return map;
    let mod;
    try {
        mod = (await createWorkspaceLoader(orgRoot).import(orgPath));
    }
    catch {
        // A broken/unparseable org.ts is reported loudly by pull app's own
        // earlier sentinel checks elsewhere; degrade quietly here rather than
        // pile a second failure onto an unrelated resolution step.
        return map;
    }
    for (const cloudLink of Object.values(mod.org?.cloudLinks ?? {})) {
        const cloudLinkName = cloudLink.name;
        if (typeof cloudLinkName !== "string")
            continue;
        for (const [key, procedure] of Object.entries(cloudLink.procedures ?? {})) {
            const { name, databaseName, schemaName, parameterTypes } = procedure;
            if (typeof name !== "string" ||
                typeof databaseName !== "string" ||
                typeof schemaName !== "string" ||
                !Array.isArray(parameterTypes) ||
                !parameterTypes.every((p) => typeof p === "string")) {
                continue;
            }
            map.set(procedureDiscriminator(cloudLinkName, name, databaseName, schemaName, parameterTypes), key);
        }
    }
    return map;
}
